'use strict';
const governance=globalThis.RasnikiSystematics,field=id=>document.getElementById(id);let governanceStore=governance.create();
function options(node,rows){node.replaceChildren();for(const [value,label] of rows){const option=document.createElement('option');option.value=String(value);option.textContent=label;node.append(option);}}
function current(){return governanceStore.proposals.find(p=>String(p.id)===field('proposal').value);}
function details(){const p=current();for(const id of ['vote','amend','apply'])field(id).disabled=!p||p.state!=='open';if(!p){field('proposal-details').textContent='No proposal selected.';options(field('member'),[]);field('amend-wording').value='';field('amend-reason').value='';return;}const o=governance.outcome(p),system=governanceStore.systems.find(s=>s.id===p.system),stale=p.baseRevision!==system.revision;field('proposal-details').textContent=[p.title+' · revision '+p.revision+' · '+p.state,p.wording,p.reason,'Result: '+o.result+' · yes '+o.yes+' · no '+o.no+' · abstain '+o.abstain+' · participation '+o.cast+'/'+p.members.length+' · quorum '+o.quorum,stale?'System has changed: amend before applying.':'Based on current system revision.',...p.votes.map(v=>v.member+': '+v.choice+' — '+v.reason),'Prior rounds: '+p.history.length].join('\n');options(field('member'),p.members.map(m=>[m,m]));field('amend-wording').value=p.wording;field('amend-reason').value=p.reason;field('apply').disabled=p.state!=='open'||o.result!=='accepted'||stale;}
function render(keep){options(field('system'),governanceStore.systems.map(s=>[s.id,s.name]));options(field('proposal'),governanceStore.proposals.map(p=>[p.id,p.title+' · '+p.state]));if(keep)field('proposal').value=String(keep);field('definitions').replaceChildren();for(const s of governanceStore.systems){const article=document.createElement('article'),heading=document.createElement('h3'),text=document.createElement('p');heading.textContent=s.name+' · revision '+s.revision;text.textContent=s.wording;article.append(heading,text);field('definitions').append(article);}details();}
function perform(fn){try{fn();field('status').textContent='Local record updated. No remote action or voter verification occurred.';}catch(error){field('status').textContent=error.message;}}
field('propose').addEventListener('click',()=>perform(()=>{const p=governance.propose(governanceStore,{system:field('system').value,title:field('title').value,wording:field('wording').value,reason:field('reason').value,members:field('members').value});render(p.id);}));
field('proposal').addEventListener('change',details);field('vote').addEventListener('click',()=>perform(()=>{const p=current();if(!p)throw Error('Select a proposal');governance.vote(p,field('member').value,field('choice').value,field('vote-reason').value);details();}));field('amend').addEventListener('click',()=>perform(()=>{const p=current();if(!p)throw Error('Select a proposal');governance.amend(governanceStore,p,field('amend-wording').value,field('amend-reason').value);details();}));field('apply').addEventListener('click',()=>perform(()=>{const p=current();if(!p)throw Error('Select a proposal');governance.apply(governanceStore,p);render(p.id);}));
field('export').addEventListener('click',()=>perform(()=>{const notes={};for(const id of ['observation','interpretation','claim','method','uncertainty'])notes[id]=field(id).value;const url=URL.createObjectURL(new Blob([governance.pack(governanceStore,notes)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='rasniki-systematics-records.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}));
field('clear').addEventListener('click',()=>{governanceStore=governance.create();for(const id of ['title','wording','reason','members','vote-reason','amend-wording','amend-reason','observation','interpretation','claim','method','uncertainty'])field(id).value='';render();field('status').textContent='Local collection reset. Downloaded and external records are unchanged.';});render();
